import{_ as t,o as a,c as i,ag as n}from"./chunks/framework.D9ghT4bC.js";const h=JSON.parse('{"title":"UncivCN Features","description":"","frontmatter":{},"headers":[],"relativePath":"UncivCN/Features.md","filePath":"UncivCN/Features.md"}'),o={name:"UncivCN/Features.md"};function r(s,e,l,c,d,u){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="uncivcn-features" tabindex="-1">UncivCN Features <a class="header-anchor" href="#uncivcn-features" aria-label="Permalink to &quot;UncivCN Features&quot;">​</a></h1><p>This page describes the features the UncivCN branch adds over upstream. Version in brackets = when the feature was introduced.</p><h2 id="lua-scripting-since-4-20-8-2-continuously-extended" tabindex="-1">Lua scripting (since 4.20.8.2, continuously extended) <a class="header-anchor" href="#lua-scripting-since-4-20-8-2-continuously-extended" aria-label="Permalink to &quot;Lua scripting (since 4.20.8.2, continuously extended)&quot;">​</a></h2><p>Mods can attach Lua scripts for logic far beyond plain JSON:</p><ul><li><strong>Triggers</strong>: via Unique syntax (e.g. <code>LuaEvent</code>) or game lifecycle hooks</li><li><strong>ctx context object</strong>: scripts can access <code>civ</code>, <code>city</code>, <code>unit</code>, <code>tile</code>, <code>game</code> APIs</li><li><strong>Tooling</strong>: the built-in mod checker can lint mod Lua errors (4.20.8.4); convenience APIs like <code>game.findTiles</code> (after 4.20.8.2)</li></ul><p>Full tutorial: <a href="/Unciv/Modders/Lua-Modding.html">Lua modding</a>.</p><h2 id="mirrored-and-ring-maps-since-4-20-7-3-4-20-7-4-4-21-0" tabindex="-1">Mirrored and ring maps (since 4.20.7.3 / 4.20.7.4 / 4.21.0) <a class="header-anchor" href="#mirrored-and-ring-maps-since-4-20-7-3-4-20-7-4-4-21-0" aria-label="Permalink to &quot;Mirrored and ring maps (since 4.20.7.3 / 4.20.7.4 / 4.21.0)&quot;">​</a></h2><ul><li><strong>Three mirrored map modes</strong>: selectable when creating a game; resources are also mirrored symmetrically (4.20.7.4)</li><li><strong>Ring maps</strong>: the map wraps around; the radius parity restriction for rotationally symmetric maps is lifted (4.20.17.2)</li></ul><h2 id="unit-pins-map-pins-4-20-17-2" tabindex="-1">Unit pins / map pins (4.20.17.2) <a class="header-anchor" href="#unit-pins-map-pins-4-20-17-2" aria-label="Permalink to &quot;Unit pins / map pins (4.20.17.2)&quot;">​</a></h2><p>Two independent toggles on the world screen, left of the minimap in the bottom-right:</p><ul><li><strong>Unit pin</strong>: when enabled, click any unit (including foreign units) to attach a note, shown right below the unit&#39;s figure; click again to edit or delete; a picker appears when multiple units share a tile</li><li><strong>Map pin</strong>: click any tile (including empty ones) to attach a note, shown on the tile with priority over food/production/gold icons</li></ul><p>Notes are stored in the <code>{saveName}_notes</code> file.</p><h2 id="tile-claim-pre-upstream-continuously-maintained" tabindex="-1">Tile claim (pre-upstream, continuously maintained) <a class="header-anchor" href="#tile-claim-pre-upstream-continuously-maintained" aria-label="Permalink to &quot;Tile claim (pre-upstream, continuously maintained)&quot;">​</a></h2><p>Cities can claim nearby tiles and swap tiles; the feature keeps adapting as upstream evolves.</p><h2 id="auto-lock-citizens-button-4-21-0-1" tabindex="-1">Auto-lock citizens button (4.21.0.1) <a class="header-anchor" href="#auto-lock-citizens-button-4-21-0-1" aria-label="Permalink to &quot;Auto-lock citizens button (4.21.0.1)&quot;">​</a></h2><p>A new <strong>Auto lock</strong> button in the bottom-right of the city screen <strong>permanently toggles</strong> between &quot;don&#39;t lock citizens&quot; and &quot;lock citizens&quot; working-tile strategies, replacing the original manual per-turn locking.</p><h2 id="rng-re-rollable-on-load-4-21-0-1" tabindex="-1">RNG re-rollable on load (4.21.0.1) <a class="header-anchor" href="#rng-re-rollable-on-load-4-21-0-1" aria-label="Permalink to &quot;RNG re-rollable on load (4.21.0.1)&quot;">​</a></h2><p>In single-player, loading a save no longer produces the same RNG sequence. Since 4.21.0.1 this is <strong>disabled in multiplayer</strong> to keep games fair.</p><h2 id="export-import-new-game-settings-to-clipboard-4-21-5-1" tabindex="-1">Export / import new game settings to clipboard (4.21.5.1) <a class="header-anchor" href="#export-import-new-game-settings-to-clipboard-4-21-5-1" aria-label="Permalink to &quot;Export / import new game settings to clipboard (4.21.5.1)&quot;">​</a></h2><p>When creating a game you can copy all current settings to the clipboard, or paste them back, making it easy to share opening configurations.</p><h2 id="polling-multiplayer-4-20-8-1" tabindex="-1">Polling multiplayer (4.20.8.1) <a class="header-anchor" href="#polling-multiplayer-4-20-8-1" aria-label="Permalink to &quot;Polling multiplayer (4.20.8.1)&quot;">​</a></h2><p>Adds a <strong>polling multiplayer</strong> mode on top of the dynamic-turn system: the same turn is split into fixed-length time slices, and the save is passed between players slice by slice, capping the wait from &quot;as long as the opponent takes&quot; to a few seconds.</p><ul><li>After checking Online Multiplayer when creating a game, a Polling interval dropdown appears (Off / 5s / 10s / 15s / 20s / 30s)</li><li>Online status of other players is visible (4.20.8.4)</li></ul><p>Full mechanics: <a href="./Polling-multiplayer.html">Polling multiplayer</a>.</p><h2 id="default-server-4-21-0-1" tabindex="-1">Default server (4.21.0.1) <a class="header-anchor" href="#default-server-4-21-0-1" aria-label="Permalink to &quot;Default server (4.21.0.1)&quot;">​</a></h2><p>The default multiplayer server is <code>http://sp.unciv.cn:30123</code>.</p><h2 id="save-version-isolation-4-20-17-2" tabindex="-1">Save version isolation (4.20.17.2) <a class="header-anchor" href="#save-version-isolation-4-20-17-2" aria-label="Permalink to &quot;Save version isolation (4.20.17.2)&quot;">​</a></h2><p>Older clients cannot load saves from newer versions, preventing save corruption from version mixing.</p><h2 id="mergeaction-extended-json-system-4-20-7-3" tabindex="-1">MergeAction extended JSON system (4.20.7.3) <a class="header-anchor" href="#mergeaction-extended-json-system-4-20-7-3" aria-label="Permalink to &quot;MergeAction extended JSON system (4.20.7.3)&quot;">​</a></h2><p>Extends <code>_mergeAction</code> (field-level merging) beyond upstream: mods can incrementally modify ruleset objects instead of replacing them wholesale. Also adds several new Countables parameter types and Amount-compatible Countables (4.20.8.2).</p><p>Tutorial: <a href="/Unciv/Modders/Mod-file-structure/6-MergeActions.html">Merge Actions</a>.</p><h2 id="history-bundled-uccc-mod-4-21-0-1-→-reverted-in-4-21-5-1" tabindex="-1">History: bundled UCCC mod (4.21.0.1 → reverted in 4.21.5.1) <a class="header-anchor" href="#history-bundled-uccc-mod-4-21-0-1-→-reverted-in-4-21-5-1" aria-label="Permalink to &quot;History: bundled UCCC mod (4.21.0.1 → reverted in 4.21.5.1)&quot;">​</a></h2><p>4.21.0.1 shipped with the UCCC mod bundled in the game; since 4.21.5.1 the game no longer bundles any mods — download mods separately.</p>',33)])])}const m=t(o,[["render",r]]);export{h as __pageData,m as default};
